namespace {
using Json = nlohmann::json;
Json report = {{"created", 0}, {"initialized", 0}, {"destroyed", 0}, {"generated", 0}};
struct Session {
    std::string path;
    bool ready = false;
    int context = 16384;
};

rac_result_t Create(const char* model, const char* config, void** out) {
    auto* session = new Session;
    session->path = model == nullptr ? "" : model;
    if (config != nullptr) {
        report["config"] = Json::parse(config);
        session->context = std::max(report["config"].value("context_length", 16384), 16384);
        report["config"]["context_length"] = session->context;
    }
    report["created"] = report["created"].get<int>() + 1;
    report["model_path"] = session->path;
    *out = session;
    return RAC_SUCCESS;
}
rac_result_t Initialize(void* impl, const char* path) {
    if (std::getenv("WALLY_TEST_FAIL_LOAD") != nullptr) return RAC_ERROR_MODEL_LOAD_FAILED;
    auto* session = static_cast<Session*>(impl);
    session->path = path;
    session->ready = true;
    report["initialized"] = report["initialized"].get<int>() + 1;
    return RAC_SUCCESS;
}
rac_result_t Generate(void* impl, const char* prompt, const rac_llm_options_t*,
                      rac_llm_result_t* result) {
    if (!static_cast<Session*>(impl)->ready) return RAC_ERROR_NOT_INITIALIZED;
    report["generated"] = report["generated"].get<int>() + 1;
    report["last_prompt"] = prompt;
    *result = {};
    constexpr char text[] = "local harness reply";
    result->text = static_cast<char*>(std::malloc(sizeof(text)));
    std::memcpy(result->text, text, sizeof(text));
    result->prompt_tokens = 3;
    result->completion_tokens = 3;
    result->total_tokens = 6;
    return RAC_SUCCESS;
}
rac_result_t Stream(void* impl, const char* prompt, const rac_llm_options_t*,
                    rac_llm_stream_callback_fn callback, void* user) {
    if (!static_cast<Session*>(impl)->ready) return RAC_ERROR_NOT_INITIALIZED;
    report["generated"] = report["generated"].get<int>() + 1;
    report["last_prompt"] = prompt;
    callback("local harness reply", RAC_FALSE, nullptr, 3, user);
    callback("", RAC_TRUE, "stop", 0, user);
    return RAC_SUCCESS;
}
rac_result_t Info(void* impl, rac_llm_info_t* info) {
    const auto* session = static_cast<Session*>(impl);
    *info = {};
    info->is_ready = session->ready ? RAC_TRUE : RAC_FALSE;
    info->current_model = session->path.c_str();
    info->context_length = session->context;
    info->supports_streaming = RAC_TRUE;
    return RAC_SUCCESS;
}
rac_result_t Ok(void*) { return RAC_SUCCESS; }
void Destroy(void* impl) {
    report["destroyed"] = report["destroyed"].get<int>() + 1;
    delete static_cast<Session*>(impl);
}

const rac_llm_service_ops_t ops = [] {
    rac_llm_service_ops_t value{};
    value.create = Create;
    value.initialize = Initialize;
    value.generate = Generate;
    value.generate_stream = Stream;
    value.get_info = Info;
    value.cancel = Ok;
    value.cleanup = Ok;
    value.destroy = Destroy;
    return value;
}();
const uint32_t formats[] = {RAC_MODEL_FORMAT_ID_GGUF};
const rac_engine_vtable_t engine = [] {
    rac_engine_vtable_t value{};
    value.metadata.abi_version = RAC_PLUGIN_API_VERSION;
    value.metadata.name = "llamacpp";
    value.metadata.display_name = "Hermetic harness test backend";
    value.metadata.priority = 100000;
    value.metadata.formats = formats;
    value.metadata.formats_count = 1;
    value.llm_ops = &ops;
    return value;
}();
std::optional<std::string> Environment(const char* name) {
    const char* value = std::getenv(name);
    return value == nullptr ? std::nullopt : std::optional<std::string>(value);
}
}  // namespace

int main(int argc, char** argv) {
    rac_logger_set_min_level(RAC_LOG_ERROR);
    if (rac_plugin_register(&engine) != RAC_SUCCESS) return 90;
    if (const char* token = std::getenv("WALLY_TEST_SEED_CLOUD")) {
        // Exercise the production platform store: Windows uses a DPAPI blob
        // named credentials.dat, while POSIX uses a protected JSON document.
        wally::account::Credentials credentials;
        credentials.console_url = wally::account::DefaultConsoleUrl();
        credentials.email = "harness@example.test";
        credentials.access_token = token;
        credentials.expires_at = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count() + 3600;
        std::string error;
        if (!wally::account::Save(credentials, &error)) {
            std::fprintf(stderr, "fixture credential setup failed: %s\n", error.c_str());
            return 92;
        }
    }
    // Register before CLI parsing; pre-bootstrapping here would mask --home
    // regressions in the production launch path.
    std::map<std::string, std::optional<std::string>> original;
    for (const char* name : {"OPENCODE_CONFIG_CONTENT", "OPENCLAW_CONFIG_PATH", "OPENCLAW_STATE_DIR",
                             "CUSTOM_BASE_URL", "HERMES_MODEL", "HERMES_INFERENCE_MODEL",
                             "HERMES_INFERENCE_PROVIDER", "RUNANYWHERE_API_KEY",
                             "ANTHROPIC_BASE_URL", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_MODEL",
                             "CLAUDE_CODE_MAX_CONTEXT_TOKENS"}) {
        original.emplace(name, Environment(name));
    }
    const int status = wally_run_main(argc, argv);
    report["stopped"] = rac_server_is_running() == RAC_FALSE;
    report["environment_restored"] = true;
    for (const auto& [name, value] : original) {
        if (Environment(name.c_str()) != value) report["environment_restored"] = false;
    }
    if (const char* path = std::getenv("WALLY_TEST_BACKEND_REPORT")) {
        std::ofstream(path) << report.dump(2);
    }
    return status;
}

/**
 * @file model_cache.h
 * @brief On-disk cache of the hosted model ids the console advertises.
 *
 * A harness launch validates a `-m <id>` against this cache so a typo is caught
 * before the tool starts, without a network round-trip. The read paths never
 * touch the network and never block; the refresh is the only thing that does,
 * and it is best-effort and fire-and-forget. Validation fails open: an empty
 * cache (never refreshed, or offline) blocks nothing.
 *
 * Lives in the profile dir beside the credential and preferences files, so it
 * follows `WALLY_PROFILE_DIR`.
 */

#ifndef WALLY_ACCOUNT_MODEL_CACHE_H
#define WALLY_ACCOUNT_MODEL_CACHE_H

#include <cstdint>
#include <string>
#include <vector>

#include "account/credentials.h"

namespace wally::account {

/// {ProfileDirectory}/models.json, or empty when no home resolves.
std::string ModelCachePath();

/// The hosted model ids last written to the cache. Empty when the cache is
/// missing, unreadable, or was never refreshed.
std::vector<std::string> CachedModelIds();

/// Whether the cache holds any ids. False is the "cannot validate, fail open"
/// signal for the launch path.
bool CacheHasModels();

/// Whether `id` is one the console advertised as of the last refresh.
bool ModelIsCached(const std::string& id);

/// Fetch the catalog now, with `credentials` already in hand, and overwrite the
/// cache. Blocking, best-effort: a failure (offline, expired token) leaves the
/// old cache untouched and is not reported. Use right after `wally login`.
void RefreshModelCache(const Credentials& credentials);

/// Fetch the catalog now with `credentials` and overwrite the cache, reporting
/// the outcome. Blocking. Returns true on success (cache written). On false,
/// `*busy` is set true when the console was rate-limited or unreachable (a "try
/// again" case) rather than a hard failure. `busy` may be null.
bool RefreshModelCacheNow(const Credentials& credentials, bool* busy);

/// If the cache is older than `ttl_seconds` (or absent), refresh it on a
/// detached thread and return immediately. Never blocks, never reports. A
/// no-op when the cache is fresh or no session is stored.
void RefreshModelCacheIfStale(std::int64_t ttl_seconds);

/// Delete the cache file. The catalog is account-scoped, so `wally logout`
/// clears it along with the credential. A no-op when there is nothing to remove.
void ClearModelCache();

/// The launch-path staleness threshold: a day. Exposed so callers share it.
constexpr std::int64_t kModelCacheTtlSeconds = 24LL * 60 * 60;

}  // namespace wally::account

#endif  // WALLY_ACCOUNT_MODEL_CACHE_H

#include "account/model_cache.h"

#include <chrono>
#include <filesystem>
#include <fstream>
#include <string>
#include <system_error>
#include <thread>
#include <vector>

#include <nlohmann/json.hpp>

#include "account/console.h"

namespace wally::account {
namespace {

namespace fs = std::filesystem;
using Json = nlohmann::json;

constexpr const char* kFileName = "models.json";
constexpr const char* kModelsKey = "models";
constexpr const char* kFetchedAtKey = "fetched_at";

std::int64_t NowSeconds() {
    return std::chrono::duration_cast<std::chrono::seconds>(
               std::chrono::system_clock::now().time_since_epoch())
        .count();
}

Json ReadDocument() {
    const std::string path = ModelCachePath();
    if (path.empty()) {
        return Json::object();
    }
    std::ifstream file(path, std::ios::binary);
    if (!file.good()) {
        return Json::object();
    }
    Json parsed = Json::parse(file, nullptr, /*allow_exceptions=*/false);
    return parsed.is_object() ? parsed : Json::object();
}

/// Atomic replace: a sibling temp then a rename, so a reader (or a launch
/// racing a refresh) never sees a half-written file, and a killed write leaves
/// the previous cache intact.
void WriteCache(const std::vector<std::string>& ids) {
    const std::string path = ModelCachePath();
    if (path.empty()) {
        return;
    }
    const fs::path target(path);
    std::error_code ec;
    fs::create_directories(target.parent_path(), ec);
    if (ec) {
        return;
    }
    Json document;
    document[kFetchedAtKey] = NowSeconds();
    document[kModelsKey] = ids;

    const fs::path temp = target.parent_path() / (std::string(kFileName) + ".tmp");
    {
        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
        if (!out.good()) {
            return;
        }
        out << document.dump(2) << '\n';
        out.flush();
        if (!out.good()) {
            return;
        }
    }
    fs::rename(temp, target, ec);
    if (ec) {
        fs::remove(temp, ec);
    }
}

bool IsStale(std::int64_t ttl_seconds) {
    const Json document = ReadDocument();
    const auto it = document.find(kFetchedAtKey);
    if (it == document.end() || !it->is_number_integer()) {
        return true;  // never written, or malformed
    }
    return NowSeconds() - it->get<std::int64_t>() > ttl_seconds;
}

}  // namespace

std::string ModelCachePath() {
    const std::string directory = ProfileDirectory();
    if (directory.empty()) {
        return {};
    }
    return (fs::path(directory) / kFileName).string();
}

std::vector<std::string> CachedModelIds() {
    const Json document = ReadDocument();
    const auto it = document.find(kModelsKey);
    if (it == document.end() || !it->is_array()) {
        return {};
    }
    std::vector<std::string> ids;
    for (const Json& entry : *it) {
        if (entry.is_string()) {
            std::string id = entry.get<std::string>();
            if (!id.empty()) {
                ids.push_back(std::move(id));
            }
        }
    }
    return ids;
}

bool CacheHasModels() {
    return !CachedModelIds().empty();
}

bool ModelIsCached(const std::string& id) {
    for (const std::string& cached : CachedModelIds()) {
        if (cached == id) {
            return true;
        }
    }
    return false;
}

bool RefreshModelCacheNow(const Credentials& credentials, bool* busy) {
    if (busy != nullptr) {
        *busy = false;
    }
    if (!credentials.signed_in()) {
        return false;
    }
    const ConsoleClient console;
    std::vector<ModelInfo> models;
    std::string error;
    const IdentityResult result =
        console.FetchModels(credentials.console_url, credentials.access_token, &models, &error);
    if (result != IdentityResult::Ok) {
        // Rate-limited or unreachable is a "try again", anything else a hard fail.
        if (busy != nullptr) {
            *busy = result == IdentityResult::Unavailable;
        }
        return false;
    }
    std::vector<std::string> ids;
    ids.reserve(models.size());
    for (const ModelInfo& model : models) {
        if (!model.id.empty()) {
            ids.push_back(model.id);
        }
    }
    WriteCache(ids);
    return true;
}

void RefreshModelCache(const Credentials& credentials) {
    RefreshModelCacheNow(credentials, nullptr);  // best-effort, outcome ignored
}

void ClearModelCache() {
    const std::string path = ModelCachePath();
    if (path.empty()) {
        return;
    }
    std::error_code ec;
    fs::remove(path, ec);
}

void RefreshModelCacheIfStale(std::int64_t ttl_seconds) {
    if (!IsStale(ttl_seconds)) {
        return;
    }
    // Detached and self-contained: it loads its own credentials and writes the
    // file atomically, so nothing it touches outlives its own stack. The launch
    // that spawned it blocks on the wrapped tool, so it has time to finish; a
    // fast-exiting caller just leaves the previous cache in place.
    std::thread([] {
        Credentials credentials;
        std::string error;
        if (Load(&credentials, &error) && credentials.signed_in()) {
            RefreshModelCache(credentials);
        }
    }).detach();
}

}  // namespace wally::account

